// exports.h - the firmware's export table (exports_table.S, generated by tools/gen_exports.py):
// every symbol a compiled program may call, sorted by name.
#pragma once

#include <stdint.h>

struct RtExport {
  const char *name;
  void *addr;
};

extern "C" const RtExport rt_exports[];
extern "C" const uint32_t rt_exports_count;

// Address of an exported symbol, or nullptr.
void *rt_find_export(const char *name);
